ft.setSwapBytes(true); // \u6211\u4eec\u9700\u8981\u4ea4\u6362\u989c\u8272\u5b57\u8282\uff08\u5b57\u8282\u5e8f\uff09\n\n  // \u5728\u521d\u59cb\u5316 TFT \u4e4b\u524d\u521d\u59cb\u5316 SD\n  if (!SD.begin(SD_CS)) {\n    Serial.println(F("SD.begin \u5931\u8d25!"));\n    return;\n  }\n  Serial.println("\\r\\n\u521d\u59cb\u5316\u5b8c\u6210.");\n\n  // JPEG \u56fe\u50cf\u53ef\u4ee5\u6309\u6bd4\u4f8b\u7f29\u653e\uff0c\u6bd4\u4f8b\u56e0\u5b50\u4e3a 1\u30012\u30014 \u6216 8\n  TJpgDec.setJpgScale(1);\n\n  // \u89e3\u7801\u5668\u5fc5\u987b\u6307\u5b9a\u4e0a\u9762\u5b9a\u4e49\u7684\u6e32\u67d3\u51fd\u6570\u7684\u786e\u5207\u540d\u79f0\n  TJpgDec.setCallback(tft_output);\n\n  if(WiFi.status() == WL_CONNECTED){\n    if(getLocation() && getStaticMapImage(host, getPath().c_str(), mapFile)){\n      TJpgDec.drawSdJpg(0, 0, mapFile);\n    }\n  }\n}\n')),(0,l.yg)("p",null,"\u8be5\u9879\u76ee\u7684\u5b8c\u6574\u7a0b\u5e8f\u53ef\u4ee5\u5728\u4ee5\u4e0b\u94fe\u63a5\u4e2d\u627e\u5230\u3002"),(0,l.yg)("div",{class:"github_container",style:{textAlign:"center"}},(0,l.yg)("a",{class:"github_item",href:"https://github.com/limengdu/XIAO-ESP32S3-Geolocation/blob/main/IP-address-location-method/IP-address-location-method.ino"},(0,l.yg)("strong",null,(0,l.yg)("span",null,(0,l.yg)("font",{color:"FFFFFF",size:"4"}," \u4e0b\u8f7d\u4ee3\u7801")))," ",(0,l.yg)("svg",{"aria-hidden":"true",focusable:"false",role:"img",className:"mr-2",viewBox:"-3 10 9 1",width:16,height:16,fill:"currentColor",style:{textAlign:"center",display:"inline-block",userSelect:"none",verticalAlign:"text-bottom",overflow:"visible"}},(0,l.yg)("path",{d:"M8 0c4.42 0 8 3.58 8 8a8.013 8.013 0 0 1-5.45 7.59c-.4.08-.55-.17-.55-.38 0-.27.01-1.13.01-2.2 0-.75-.25-1.23-.54-1.48 1.78-.2 3.65-.88 3.65-3.95 0-.88-.31-1.59-.82-2.15.08-.2.36-1.02-.08-2.12 0 0-.67-.22-2.2.82-.64-.18-1.32-.27-2-.27-.68 0-1.36.09-2 .27-1.53-1.03-2.2-.82-2.2-.82-.44 1.1-.16 1.92-.08 2.12-.51.56-.82 1.28-.82 2.15 0 3.06 1.86 3.75 3.64 3.95-.23.2-.44.55-.51 1.07-.4